draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw stick figure representing gene
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Animate gene replication
  ctx.save();
  ctx.translate(W/2, H/2 + 80);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.arc(0, 0, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(-10, 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, 20);
  ctx.lineTo(10, 30);
  ctx.stroke();
  ctx.restore();

  // Draw double helix around gene
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2);
  ctx.lineTo(W/2 - 30, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2);
  ctx.lineTo(W/2 + 30, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 20 + Math.sin(t)*10);
  ctx.lineTo(W/2 + 30, H/2 + 20 - Math.sin(t)*10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 60 + Math.sin(t)*10);
  ctx.lineTo(W/2 + 30, H/2 + 60 - Math.sin(t)*10);
  ctx.stroke();

  ctx.restore();
}
